import { CfnOutput, RemovalPolicy, Stack, StackProps } from "aws-cdk-lib";
import * as iam from "aws-cdk-lib/aws-iam";
import * as secretsmanager from "aws-cdk-lib/aws-secretsmanager";
import { Construct } from "constructs";
import { SureVoteConfig } from "./config";

export interface DatabaseSecretsStackProps extends StackProps {
    readonly settings: SureVoteConfig;
}

/** The database roles, one secret each. The value is generated by Secrets Manager and never in the template. */
const ROLES = {
    owner: { id: "OwnerSecret", username: "surevote", about: "the table owner; runs Flyway and the role grants" },
    writer: { id: "WriterSecret", username: "surevote_app", about: "the writer role for workspace, demo, and ingest" },
    reader: { id: "PublicReaderSecret", username: "surevote_public", about: "the public surface's read-only role" },
    dispute: { id: "DisputeSecret", username: "surevote_dispute", about: "the public surface's dispute-only role" },
} as const;

type Role = keyof typeof ROLES;

/**
 * Which surface may read which role's secret. Only the workspace gets the owner: it alone migrates and grants
 * (`SUREVOTE_JDBC_USER`). The other surfaces refuse to start with the owner credential set.
 */
export const SURFACE_SECRETS: Record<string, Role[]> = {
    workspace: ["owner", "writer"],
    public: ["reader", "dispute"],
    demo: ["writer"],
    ingest: ["writer"],
};

export class DatabaseSecretsStack extends Stack {
    readonly secrets: Record<Role, secretsmanager.Secret>;
    readonly access: Record<string, iam.ManagedPolicy>;

    constructor(scope: Construct, id: string, props: DatabaseSecretsStackProps) {
        super(scope, id, props);
        const secret = (role: Role) => new secretsmanager.Secret(this, ROLES[role].id, {
            description: `SureVote database credential for ${ROLES[role].about}`,
            generateSecretString: {
                secretStringTemplate: JSON.stringify({ username: ROLES[role].username }),
                generateStringKey: "password",
                excludePunctuation: true,
                passwordLength: 40,
            },
            removalPolicy: RemovalPolicy.RETAIN,
        });
        this.secrets = { owner: secret("owner"), writer: secret("writer"), reader: secret("reader"), dispute: secret("dispute") };
        this.access = {};
        for (const [surface, roles] of Object.entries(SURFACE_SECRETS)) {
            const name = surface.charAt(0).toUpperCase() + surface.slice(1);
            this.access[surface] = new iam.ManagedPolicy(this, name + "DatabaseAccess", {
                description: `Lets the ${surface} surface read its database credentials: ${roles.join(", ")}`,
                statements: [
                    new iam.PolicyStatement({
                        actions: ["secretsmanager:GetSecretValue"],
                        resources: roles.map((role) => this.secrets[role].secretArn),
                    }),
                ],
            });
            new CfnOutput(this, name + "DatabaseAccessPolicy", { value: this.access[surface].managedPolicyArn });
        }
    }
}
